package android.view; public class View {public View(){}public View(android.content.Context ctx){context=ctx;} public android.content.Context context=new android.content.Context();public android.content.Context getContext(){return context;}public android.content.res.Resources getResources(){return context.res;}public View root=this;public ViewParent parent;public int x,y,w,h,visibility,layouts;public boolean attached=true;public ViewGroup.LayoutParams params;public final java.util.Map<Integer,View> children=new java.util.HashMap<>();public View getRootView(){return root;}public ViewParent getParent(){return parent;}public View findViewById(int id){return children.get(id);}public boolean isAttachedToWindow(){return attached;}public boolean isShown(){return attached&&visibility==0;}public int getVisibility(){return visibility;}public void setVisibility(int v){visibility=v;}public int getWidth(){return w;}public int getHeight(){return h;}public void getLocationInWindow(int[] p){p[0]=x;p[1]=y;}public WindowInsets window;public WindowInsets getRootWindowInsets(){return root.window;}public void invalidate(){}public ViewGroup.LayoutParams getLayoutParams(){return params;}public void setLayoutParams(ViewGroup.LayoutParams p){params=p;layouts++;}public int id,rtl,left,top;public static int generateViewId(){return 99;}public void setId(int i){id=i;}public int getId(){return id;}public void setImportantForAccessibility(int i){}public int getLeft(){return left;}public int getTop(){return top;}public int getLayoutDirection(){return rtl;}public boolean isInLayout(){return false;}public boolean post(Runnable r){r.run();return true;}public int pl,pt,pr,pb; public int getPaddingTop(){return pt;} public int getPaddingLeft(){return pl;} public int getPaddingRight(){return pr;} public int getPaddingBottom(){return pb;} public void setPadding(int l,int t,int r,int b){pl=l;pt=t;pr=r;pb=b;}public int getScrollX(){return 0;}public int getScrollY(){return 0;}public float getY(){return top+ty;}public boolean getLocalVisibleRect(android.graphics.Rect r){r.set(0,0,w,h);return w>0&&h>0;}public float sx,sy,tx,ty;public float getAlpha(){return 1f;}public void setAlpha(float a){}public void setTranslationX(float x){tx=x;}public void setTranslationY(float y){ty=y;}public void setScaleX(float x){sx=x;}public void setScaleY(float y){sy=y;}public android.graphics.Matrix getMatrix(){return new android.graphics.Matrix();}}